/* Месяцеслов «Православных» — 02.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M02: SaintRec[] = [
  { key: "02-01", name: "Прп. Макария Великого, Египетского", kind: "saint", desc: "Родился в Египте около 301 года. С любовью и усердием послужил он своим родителям в старости, исполняя заповедь о почитании родителей, и по кончине их сделался совершенно свободным от житейских забот." },
  { key: "02-01", name: "свт. Марка Евгеника, архиепископа Ефесского", kind: "saint", desc: "Святой Марк Евгеник, архиепископ Ефесский, был знаменитым защитником православия на Флорентийском Соборе. Ничто не могло склонить его к унии. Тайно удалившись из Флоренции, святой Марк ревностно убеждал жителей Константинополя отвергнуть нечестивое соглашение." },
  { key: "02-01", name: "блж. Феодора Новгородского, Христа ради юродивого", kind: "saint", desc: "Родом из Новгорода, с Торговой стороны. Подражая жизни святых, св. Феодор налагал на себя строгий пост (в среду и пятницу вообще ничего не ел), часто посещал храмы Божии и подавал щедрую милость нищим." },
  { key: "02-01", name: "прп. Макария Римлянина, Новгородского", kind: "saint", desc: "Родился в Риме в конце XV в. от благочестивых родителей. Воспитанный в строгих религиозных законах, преподобный, покинув Рим с его духовным разладом, достиг Великого Новгорода." },
  { key: "02-01", name: "Прп. Макария, постника Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Макарий, постник Печерский, в Ближних пещерах (XII), и преподобный Макарий, диакон Печерский, в Дальних пещерах (XIII–XIV), оба были диаконами." },
  { key: "02-01", name: "прп. Макария, диакона Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Макарий, постник Печерский, в Ближних пещерах (XII), и преподобный Макарий, диакон Печерский, в Дальних пещерах (XIII–XIV), оба были диаконами." },
  { key: "02-01", name: "Обретение мощей прп. Саввы Сторожевского, Звенигородского", kind: "saint", desc: "Прп. Савва Сторожевский, ученик прп. Сергия Радонежского, с юности посвятил себя монашеству. Став духовником братии и игуменом, он основал монастырь на Сторожевской горе, где наставлял иноков в молитве и трудах." },
  { key: "02-01", name: "мц. Евфрасии девы", kind: "saint", desc: "Святая мученица Евфрасия дева родилась в Никомидии в знатной семье, отличалась красотой и была христианкой. Во время Максимианова гонения на христиан правитель города принуждал Евфрасию принести жертву идолам, когда же она отказалась, приказал бить ее, а затем отдал воину на осквернение." },
  { key: "02-01", name: "прп. Макария Александрийского, иеромонаха", kind: "saint", desc: "Родился в 295 г. в Александрии. До сорока лет занимался торговлей, затем принял Святое Крещение и удалился в пустыню. Через несколько лет подвижнической жизни он был посвящен в сан пресвитера и поставлен настоятелем монастыря, называемого «" },
  { key: "02-01", name: "свт. Арсения, архиепископа Керкирского", kind: "saint", desc: "Святой Арсений, архиепископ Керкирский (IX-X вв.) родился в Палестине в царствование императора Василия I Македонянина (867-868) в семье благочестивых родителей; отец происходил из Иерусалима, мать – из Вифании." },
  { key: "02-01", name: "прп. Антония Марткопского, столпника (VI)", kind: "saint", desc: "Святого Антония прозвали Марткопским из-за любви к уединению: в переводе с грузинского «марто мкопи» означает «находящийся в одиночестве». Он был столпником, одним из 12 учеников преподобного Иоанна Зедазнийского, пришедших в Грузию в VI веке и основавших грузинское монашество." },
  { key: "02-01", name: "Сщмч. Петра Скипетрова, пресвитера", kind: "saint", desc: "Священномученик Петр родился 4 июня 1863 года в селе Станки Вязниковского уезда Владимирской губернии в семье священника Иоанна Скипетрова. После окончания Шуйского духовного училища Петр поступил во Владимирскую Духовную семинарию, которую окончил в 1884 году." },
  { key: "02-01", name: "сщмч. Николая Восторгова, пресвитера", kind: "saint", desc: "Священномученик Николай родился 21 ноября 1875 года в селе Никологорском Вязниковского уезда Владимирской губернии в семье псаломщика Евдокима Восторгова." },
  { key: "02-01", name: "мч. Феодора Гусева", kind: "saint", desc: "Мученик Феодор родился 22 апреля 1874 года в селе Сидоровском Звенигородского уезда Московской губернии в семье крестьянина Федора Гусева. Первоначальное образование он получил в сельской школе." },
  { key: "02-02", name: "Прп. Евфимия Великого, иеромонаха", kind: "saint", desc: "Преподобный Евфимий Великий происходил из города Мелитины в Армении, близ реки Евфрат. Родители его, Павел и Дионисия, знатные люди, были благочестивыми христианами." },
  { key: "02-02", name: "Евфимия схимника", kind: "saint", desc: "Иеросхимонах, подвизался в XIV веке в Киево-Печерском монастыре. Он наложил на себя обет безмолвия, открывая уста только для богослужения и молитвы. Также никакой пищи, приготовляемой на огне, святой не вкушал, а довольствовался травами." },
  { key: "02-02", name: "Лаврентия затворника (XIII–XIV), Печерских, в Дальних пещерах", kind: "saint", desc: "Подвизался в Киево-Печерском монастыре в XIII–XIV вв. Нес трудный подвиг затворничества, упражняясь в посте, молитве и богомыслии. Мощи преподобного Лаврентия почивают в Дальних (Феодосиевых) пещерах." },
  { key: "02-02", name: "прп. Евфимия Сянжемского, Вологодского", kind: "saint", desc: "Преподобный Евфимий Сянжемский, Вологодский родился в Вологде, монашеский постриг принял в Спасо-Каменном монастыре на Кубенском озере. Некоторое время он жил в уединенной келлии на реке Кубенке, а затем уступил место преподобному Александр" },
  { key: "02-02", name: "прп. Евфимия (Кереселидзе) исп., игумена (1944)", kind: "saint", desc: "Родился в деревне Самели, район Рача в 1865 году у благочестивых супругов Соломона и Марты Кереселидзе. При рождении его назвали Евстатом. После окончания церковно-приходской школы пятнадцатилетний Евстат отправился в Кутаиси, потом в Тбили" },
  { key: "02-02", name: "Сщмч. Павла Добромыслова, пресвитера", kind: "saint", desc: "Священномученик Павел родился 17 июня 1877 года в селе Поляны Рязанского уезда Рязанской губернии в семье священника Николая Григорьевича Добромыслова." },
  { key: "02-03", name: "Прп. Максима Исповедника", kind: "saint", desc: "Прп. Максим Исповедник (ок. 580-662) ‒ выдающийся богослов и защитник Православия. Родившись в Константинополе, он оставил высокий пост при императорском дворе, принял монашество и стал игуменом." },
  { key: "02-03", name: "мч. Неофита Никейского", kind: "saint", desc: "Святой мученик Неофит, родом из города Никеи, был воспитан своими родителями в строгом христианском благочестии. За доброту, воздержание и постоянную молитву Богу угодно было еще в отрочестве прославить святого Неофита даром чудотворений." },
  { key: "02-03", name: "прп. Максима Грека", kind: "saint", desc: "Прп. Максим Грек (XV–XVI в.) ‒ выдающийся богослов и переводчик, уроженец Греции. Получив блестящее образование в Европе, принял монашество на Афоне. В 1518 г." },
  { key: "02-03", name: "Мц. Агнии (Анны) девы", kind: "saint", desc: "Мц. Агния (Анна), 13-летняя христианка из Рима. Когда она отказалась поклоняться языческим богам и выходить замуж за сына римского чиновника, её пытались опозорить, отправив в дом терпимости." },
  { key: "02-03", name: "прп. Анастасия Римского, исп.", kind: "saint", desc: "Святой мученик Анастасий был учеником преподобного Максима Исповедника , вместе с ним терпел гонения от монофелитов. Он описал жизнь своего учителя. Скончался в 662 году." },
  { key: "02-03", name: "Сщмч. Илии Березовского, пресвитера", kind: "saint", desc: "Священномученик Илия (Илья Яковлевич Березовский) родился 20 июля 1890 года в селе Гляден Томского уезда Томской губернии Алтайского горного округа. Отец Илия был арестован в 1933 году и выслан в Казахстан." },
  { key: "02-03", name: "Ктиторская", year: "IV", kind: "saint", desc: "Недалеко от Ватопедского Афонского монастыря , построенного в IV веке в период царствования Константина Великого, во время сильной бури упал с корабля в море царевич Аркадий, сын императора Феодосия Великого." },
  { key: "02-03", name: "Отрада (Утешение) Ватопедская", year: "807", kind: "saint", desc: "Ватопедская икона Божией Матери находится в древнем Ватопедском монастыре на Афоне, в храме Благовещения. Название Ватопедской она получила от того, что близ этого монастыря упал в море с корабля юный царевич Аркадий и чудным заступлением Божией Матери был перенесен на берег целым и невредимым." },
  { key: "02-04", name: "Ап. от 70-ти Тимофея Ефесского", kind: "saint", desc: "Святой апостол Тимофей происходил из ликаонского города Листры в Малой Азии. Он был обращен ко Христу в 52 году святым апостолом Павлом (&dagger; ок. 67; память 29 июня)." },
  { key: "02-04", name: "прмч. Анастасия Персянина", kind: "saint", desc: "Родился в Персии. Отец его Вав был магом, знаменитым учителем чародейства, который обучил и сына своего. Анастасий, служа воином у персидского царя Хозроя, услышал о Животворящем Кресте Господнем, молва о славе и могуществе которого распространилась по всей Персии." },
  { key: "02-04", name: "прп. Макария Жабынского, Белевского чудотворца", kind: "saint", desc: "Прп. Макарий Жабынский подвизался в начале XVII века, возродив разоренную литовцами Жабынскую пустынь. Он собрал братию, основал монастырь и стал его игуменом." },
  { key: "02-04", name: "Прмч. Анастасия, диакона Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобномученик Анастасий, диакон Печерский, подвизался в Ближних пещерах в XII веке. Иеромонах Афанасий Кальнофийский называет его братом преподобного Тита пресвитера (&dagger; не ранее 1190; память 27 февраля/12 марта)." },
  { key: "02-04", name: "Иоанна Успенского", kind: "saint", desc: "Священномученик Иоанн родился 30 августа 1870 года в селе Большие Соли Ярославской губернии в семье священника Александра Успенского. Иван Александрович окончил духовное училище и в 1890 году был рукоположен в сан диакона, а уже в период на" },
  { key: "02-04", name: "Евфимия Тихонравова", kind: "saint", desc: "Священномученик Евфимий родился 17 апреля 1881 года в городе Шуе Владимирской губернии. По некоторым свидетельствам, его отец, Сергей Тихонравов, был священником." },
  { key: "02-05", name: "Прп. Геннадия Костромского, Любимоградского", kind: "saint", desc: "Святой Геннадий Костромской, в миру Григорий, родился в городе Могилеве от богатых русско-литовских бояр. С юности он отличался благочестием, любил посещать храм Божий и строго соблюдал посты, за что друзья смеялись над ним." },
  { key: "02-05", name: "Собор святых Костромской митрополии", kind: "feast", desc: "Соборный праздник святых Костромской земли был установлен в 1981 году, по инициативе архиепископа Костромского и Галичского Кассиана (Ярославского) и по благословению патриарха Московского и всея Руси Пимена." },
  { key: "02-05", name: "перенесение мощей свт. Феоктиста, архиепископа Новгородского", kind: "saint", desc: "По преставлении архиепископа Климента новгородцы с посадником своим Андреем много рассуждали о преемнике его, все, от мала до велика, возлюбили Богом назначенного, мужа смиренного и доброго, игумена Благовещенского монастыря Феоктиста." },
  { key: "02-05", name: "прп. Мавсимы Сирина, пресвитера", kind: "saint", desc: "Преподобный Мавсима Сирин жил в Сирии, близ города Кира или Кирфа. Ради спасения души он принял на себя добровольную нищету и посвятил свою жизнь служению ближним." },
  { key: "02-05", name: "прп. Саламана молчальника", kind: "saint", desc: "Преподобный Саламан молчальник был родом из города Каперсана, при реке Евфрате. Найдя на берегу реки уединенную пещеру, он затворился в ней и проводил безмолвную жизнь в молитвенных подвигах." },
  { key: "02-05", name: "свт. Павлина Милостивого, епископа Ноланского", kind: "saint", desc: "Святитель Павлин Милостивый, епископ Ноланский, происходил из благородной и богатой семьи города Бордо (Франция). Благодаря высокой образованности двадцатилетним юношей был избран в римские сенаторы, затем стал консулом и наконец губернатором области Кампании в Италии." },
  { key: "02-05", name: "Воспоминание VI Вселенского Собора", year: "680-681", kind: "feast", desc: "VI Вселенский Собор был созван императором Константином Погонатом (668–685) в Константинополе в 681 году против ереси монофелитов. На нем присутствовало 170 святых отцов, которые утвердили исповедание веры о двух волях в Иисусе Христе – Божественной и человеческой." },
  { key: "02-05", name: "Прмч. Серафима (Булашова), игумена", kind: "saint", desc: "Преподобномученик Серафим (в миру Николай Семенович Булашов) родился в 1872 году в Москве в семье раскольников-поповцев. С 1893 по 1897 год Николай служил в армии в чине старшего унтер-офицера." },
  { key: "02-05", name: "Евдокии Кузьминовой", kind: "saint", desc: "Преподобномученица Евдокия родилась 17 августа 1884 года в городе Воскресенске Звенигородского уезда Московской губернии в семье мещанина Петра Кузьминова." },
  { key: "02-05", name: "Екатерины Черкасовой", kind: "saint", desc: "Преподобномученица Екатерина родилась 4 декабря 1892 года в селе Кашино Волоколамского уезда Московской губернии в семье крестьянина Михаила Черкасова." },
  { key: "02-05", name: "мц. Милицы Кувшиновой", kind: "saint", desc: "Мученица Милица родилась 23 ноября 1891 года в селе Улиновка Кобелякского уезда Полтавской губернии в семье чиновника, служившего на железной дороге, Ивана Кувшинова." },
  { key: "02-06", name: "Прп. Ксении (в миру Евсевии) Миласской, диаконисы", kind: "saint", desc: "Преподобная Ксения (V), в миру Евсевия, была единственной дочерью знатного римского сенатора. С юности она стремилась к Богу. Чтобы избежать предстоящего ей брака, она тайно ушла из родительского дома с двумя преданными ей служанками и отплыла на корабле.", lifeId: "kseniya" },
  { key: "02-06", name: "блж. Ксении Петербургской", kind: "saint", desc: "Блж. Ксения Петербургская (ок. 1720–1803), молодая вдова, избрала подвиг юродства Христа ради, чтобы вымолить душу внезапно умершего мужа. Раздав имущество, ходила в его одежде, утверждая, что \"умерла Ксения\".", lifeId: "kseniya" },
  { key: "02-06", name: "Свт. Герасима, епископа Великопермского, Устьвымского", kind: "saint", desc: "Третий епископ новопросвещенного зырянского народа. Был возведен на Пермскую кафедру после 1416 г. Неусыпно заботился об укреплении веры Христовой среди новообращенных зырян." },
  { key: "02-06", name: "мч. Иоанна Казанского", kind: "saint", desc: "Мученик Иоанн Казанский пострадал за Христа в городе Казани 24 января 1529 года. В княжение великого князя Василия Ивановича татары напали на Нижний Новгород." },
  { key: "02-06", name: "прп. Македония, сирийского пустынника", kind: "saint", desc: "Преподобный Македоний, сирийский пустынник, жил в конце IV – начале V вв. В начале своего подвижнического пути он вел жизнь странника, скитаясь по горам Финикии, Киликии и Сирии 25 лет, а затем обрел убежище в глубоком рве и жил под открыты" },
  { key: "02-06", name: "перенесение мощей прмч. Анастасия Персянина", kind: "saint", desc: "Родился в Персии. Отец его Вав был магом, знаменитым учителем чародейства, который обучил и сына своего. Анастасий, служа воином у персидского царя Хозроя, услышал о Животворящем Кресте Господнем, молва о славе и могуществе которого распространилась по всей Персии." },
  { key: "02-07", name: "Свт. Григория Богослова, архиепископа Константинопольского", kind: "saint", desc: "Святой Григорий Богослов (326-389 гг.) был сын Григория (впоследствии епископа Назианского) и Нонны, женщины высоких нравственных правил. Еще до рождения сына она обещала посвятить его Богу и употребила все старания, чтобы склонить его волю на служение Господу." },
  { key: "02-07", name: "прп. Анатолия Оптинского, Старшего (Зерцалова)", kind: "saint", desc: "Прп. Анатолий Оптинский (Зерцалов) (1824-1894) родился в семье диакона Калужской губернии. После чудесного исцеления от чахотки, по обету, в 1853 г. поступил в Оптину пустынь, где стал духовным чадом преподобных старцев Макария и Амвросия." },
  { key: "02-07", name: "сщмч. Владимира (Богоявленского), митрополита Киевского", kind: "saint", desc: "Сщмч. Владимир (Богоявленский, 1848–1918) родился в семье священника, окончил Киевскую Духовную Академию и стал преподавателем, а затем священником. После смерти жены и ребенка принял монашество." },
  { key: "02-07", name: "Свт. Моисея, архиепископа Новгородского", kind: "saint", desc: "Родился в Новгороде, иноческий постриг принял в Тверском Отроч монастыре. По настоянию родителей он перешел в Колмов монастырь близ Новгорода, где был рукоположен в сан иеромонаха, а затем в Юрьеве монастыре возведен в архимандрита." },
  { key: "02-07", name: "прп. Поплия Сирийского", kind: "saint", desc: "Преподобный Поплий принадлежал к сословию сенаторов [1] и происходил из города Зевгма [2] на Евфрате. Избрав место на высокой горе, в тридцати верстах от города, святой Поплий построил небольшую хижину и затем роздал все полученное от родит" },
  { key: "02-07", name: "прп. Мара певца", kind: "saint", desc: "Преподобный Мар в юности отличался красивой наружностью и обладал хорошим голосом; во время праздников в честь святых мучеников он в совершенстве исполнял обязанности певца." },
  { key: "02-07", name: "Сщмч. Петра (Зверева), архиепископа Воронежского", kind: "saint", desc: "Сщмч. Петр (Зверев) (1878-1929), архиепископ Воронежский. После закрытия властями Воронежского монастыря в 1926 году был осуждён по ст. 58 УК РСФСР (контрреволюционная пропаганда), приговорён к 10 годам лагерей и сослан в Соловецкий лагерь." },
  { key: "02-07", name: "сщмч. Василия (Зеленцова), епископа Прилукского", kind: "saint", desc: "Священномученик Василий родился 8 марта 1876 года в селе Зимарово Зимаровской волости Раненбургского уезда Рязанской губернии в семье священника Иоанна Зеленцова, служившего в Боголюбской церкви в этом селе, и в крещении наречен был Василием." },
  { key: "02-07", name: "сщмч. Стефана Грачева, пресвитера", kind: "saint", desc: "Священномученик иерей Стефан Федорович Грачев родился 30 декабря 1886 года в деревне Тростная Севского уезда Орловской губернии (ныне Комаричский район Брянской области) в крестьянской семье." },
  { key: "02-07", name: "мч. Бориса Заварина", kind: "saint", desc: "Мученик Борис родился 23 апреля 1910 года в селе Копыри Ростовского уезда Ярославской губернии в семье священника Сергия Заварина [1] и его супруги Александры." },
  { key: "02-07", name: "Утоли моя печали", kind: "saint", desc: "Икона Божией Матери, именуемая &quot;Утоли моя печали&quot;, прославилась в Москве многими чудесами со второй половины XVIII века, а особенно во время чумы в 1771 году." },
  { key: "02-08", name: "Собор новомучеников и исповедников Церкви Русской", kind: "feast", desc: "Собор новомучеников и исповедников Церкви Русской празднуется 7 февраля (25 января), в случае совпадения этого числа с воскресным днем; в предшествующий этой дате воскресный день, если 7 февраля приходится на дни от понедельника до среды; в" },
  { key: "02-08", name: "Интронизация святителя Иова, Патриарха Московского, и начало Патриаршества на Руси", year: "1589", kind: "feast", desc: "Празднование установлено определением Священного Синода Русской Православной Церкви от 27 декабря 2024 года. 26 января (5 февраля) 1589 года митрополит Иов был выбран царём Фёдором Ивановичем из трёх предложенных Освященным собором кандидат" },
  { key: "02-08", name: "Прп. Ксенофонта Робейского, игумена", kind: "saint", desc: "Прп. Ксенофонт Робейский ‒ ученик св. Варлаама Хутынского, был игуменом Хутынского монастыря. Оставив игуменство, основал Троицкую обитель на реке Робейке под Новгородом." },
  { key: "02-08", name: "прп. Симеона Ветхого, игумена", kind: "saint", desc: "Преподобный Симеон Ветхий назван так в отличие от преподобного Симеона Столпника (память 1 сентября), подвизавшегося в Сирии в V веке, в детские годы ушел в пустыню в Сирии и поселился в пещере, в совершенном уединении." },
  { key: "02-08", name: "перенесение мощей прп. Феодора Студита, игумена, песнописца", kind: "saint", desc: "Родился в 758 г. в Константинополе и получил широкое и разностороннее образование. Глубоко изучив Св. Писание, святой Феодор успешно противостоял еретикам-иконоборцам в диспутах о православной вере." },
  { key: "02-08", name: "свт. Иосифа Студита, архиепископа Солунского, песнописца", kind: "saint", desc: "Святой Иосиф, архиепископ Солунский, брат преподобного Феодора Студита [1] , вместе с ним с юных лет подвизался под руководством дяди своего, преподобного Платона, основавшего монастырь в Сакудионе [2] ." },
  { key: "02-08", name: "блгв. Давида IV Возобновителя (Строителя), царя Иверии и Абхазии (1125)", kind: "saint", desc: "Святой благоверный Давид IV Возобновитель (Строитель), царь Иверии и Абхазии (1089–1125; по другим источникам 1084–1125), – выдающийся государственный, культурный и церковный деятель Грузии." },
  { key: "02-08", name: "Мч. Иоанна Попова", kind: "saint", desc: "Мученик Иоанн родился 17 января 1867 года в городе Вязьме Смоленской губернии в семье священника Воскресенской церкви города Вязьмы Василия Михайловича Попова и его супруги Веры Ивановны." },
  { key: "02-09", name: "Перенесение мощей свт. Ио а нна Златоуста", year: "438", kind: "feast", desc: "Святитель Иоанн Златоуст, архиепископ Константинопольский – один из трех вселенских святителей вместе со святителями Василием Великим и Григорием Богословом ." },
  { key: "02-10", name: "Прп. Ефрема Сирина, иеродиакона", kind: "saint", desc: "Преподобный Ефрем Сирин [1] , учитель покаяния, родился в начале IV века (год его рождения точно неизвестен) в городе Низибии (Месопотамии) в христианской семье бедных земледельцев.", lifeId: "efrem-sirin" },
  { key: "02-10", name: "прп. Феодосия Тотемского", kind: "saint", desc: "Прп. Феодосий Тотемский (Суморин), вологжанин, с юности вел благочестивую жизнь. Овдовев, он ушел в Прилуцкий монастырь. Позже, направленный в Тотьму, испросил разрешения основать там новую обитель и стал её настоятелем." },
  { key: "02-10", name: "Прп. Ефрема Новоторжского, архимандрита", kind: "saint", desc: "Прп. Ефрем Новоторжский, венгр по происхождению, прибыл на Русь вместе с братьями св. Моисеем Угрином и св. Георгием, поступив на службу к св. князю Ростовскому Борису." },
  { key: "02-10", name: "прп. Ефрема Печерского, епископа Переяславского", kind: "saint", desc: "Происходил из благородного, знатного рода и управлял хозяйством при дворе великого князя киевского Изяслава Ярославича. Тяготясь шумной и суетливой жизнью, в 1056 г." },
  { key: "02-10", name: "прп. Палладия Антиохийского (Сирийского), пустынника", kind: "saint", desc: "Преподобный Палладий пустынник подвизался в одной горной пещере близ Антиохии Сирийской. За свою подвижническую жизнь он получил от Господа дар чудотворений." },
  { key: "02-10", name: "прп. Исаака Сирина, епископа Ниневийского", kind: "saint", desc: "Преподобный Исаак Сирин родился в восточной Сирии приблизительно в начале VI века. В молодости он поступил в обитель Мар Матфея вместе с родным братом." },
  { key: "02-10", name: "Св. Феодора Богоявленского, исп., пресвитера", kind: "saint", desc: "Священноисповедник Феодор родился 26 февраля 1881 года в селе Сеславино Ярославского уезда Ярославской губернии в семье священника Павла Богоявленского и его супруги Екатерины [1] ." },
  { key: "02-10", name: "сщмч. Игнатия (Садковского), епископа Скопинского", kind: "saint", desc: "Священномученик Игнатий родился 21 октября 1887 года в Москве в семье священника Сергея Максимовича Садковского, служившего в Георгиевской на Всполье церкви, и в крещении наречен был, как и его отец, Сергеем." },
  { key: "02-10", name: "сщмч. Владимира Пищулина, пресвитера", kind: "saint", desc: "Священномученик Владимир родился 6 июня 1889 года в городе Костроме в семье чиновника Федора Пищулина, служившего в окружном суде. Окончив в 1908 году Витебскую гимназию, Владимир решил последовать занятиям своего отца и поступил на юридический факультет Московского университета." },
  { key: "02-10", name: "прмч. Варфоломея (Ратных), иеромонаха", kind: "saint", desc: "Преподобномученик Варфоломей (Ратных) родился в 1894 году в селе Матренки Киевской губернии в крестьянской семье. Окончил церковноприходскую школу. В 1913 году он поступил послушником в один из монастырей Киевской епархии." },
  { key: "02-10", name: "мц. Ольги Евдокимовой", kind: "saint", desc: "Мученица Ольга (Ольга Васильевна Евдокимова) родилась 11 июля 1896 года в селе Ново-Рождественское Раменской волости Бронницкого уезда Московской губернии." },
  { key: "02-10", name: "прп. Леонтия Михайловского (Стасевича), исп., архимандрита", kind: "saint", desc: "Преподобноисповедник Леонтий родился 20 марта 1884 года в посаде Тарноград Белгорайского уезда Люблинской губернии в благочестивой крестьянской семье Фомы и Екатерины Стасевичей и в крещении был наречен Львом." },
  { key: "02-10", name: "Тотемская-Суморинская", kind: "saint", desc: "Город Тотьма находится в Вологодской губернии. Недалеко от него в XVI веке подвизался преподобный Феодосий, прозванный, по месту своих подвигов, Тотемским." },
  { key: "02-11", name: "Перенесение мощей сщмч. Игн а тия Богоносца, епископа", year: "107", kind: "feast", desc: "Святой Игнатий Богоносец имеет особое значение для нас, потому что он близко общался с апостолами, непосредственно от них слышал христианское учение и был свидетелем распространения и развития первых христианских общин." },
  { key: "02-11", name: "Свт. Лаврентия, затворника Печерского, епископа Туровского, в Ближних пещерах", kind: "saint", desc: "Преподобный Лаврентий, затворник Печерский, епископ Туровский, в Ближних пещерах, сначала подвизался в затворе в монастыре великомученика Димитрия, построенном великим князем Изяславом в Киеве близ Печерского монастыря, а потом перешел в самую Печерскую обитель, прославился даром исцелений." },
  { key: "02-11", name: "Герасима", kind: "saint", desc: "Третий епископ новопросвещенного зырянского народа. Был возведен на Пермскую кафедру после 1416 г. Неусыпно заботился об укреплении веры Христовой среди новообращенных зырян." },
  { key: "02-11", name: "Питирима", kind: "saint", desc: "Свт. Питирим, епископ Пермский, возглавил кафедру после гибели свт. Герасима. Будучи ранее архимандритом Чудова монастыря, он ревностно проповедовал христианство среди зырян и вогулов, призывая к миру и отказу от грабежей." },
  { key: "02-11", name: "Ионы (1470), епископов Великопермских, Устьвымских", kind: "saint", desc: "Свт. Иона, епископ Великопермский (XV в.) — преемник убитого вогуличами свт. Питирима, завершивший христианизацию Великой Перми. Обратил языческие племена по рекам Вишере, Каме и Чусовой, уничтожил идолов и построил храмы с училищами." },
  { key: "02-11", name: "Собор Коми святых", kind: "feast", desc: "Дата празднования Собора – 11 февраля (29 января). Празднование внесено в месяцеслов по благословению Святейшего Патриарха Кирилла 23 марта 2015 года. Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 20" },
  { key: "02-11", name: "Собор Екатеринбургских святых", kind: "feast", desc: "Празднование учреждено в 2010 году по инициативе архиепископа Екатеринбургского Викентия и по благословению патриарха Московского и всея Руси Кирилла, днем празднования выбран день образования Екатеринбургской епархии – 11 февраля (н." },
  { key: "02-12", name: "Собор вселенских учителей и святителей Василия Великого, Григория Богослова и Иоанна Златоустого", kind: "feast", desc: "При императоре Алексее Комнине, который правил с 1081 по 1118 г., в Константинополе разгорелся спор, разделивший на три лагеря мужей, просвещенных в вопросах веры и усердных в стяжании добродетелей." },
  { key: "02-12", name: "блж. Пелагии Дивеевской (Серебренниковой)", kind: "saint", desc: "Родилась Пелагия Ивановна в 1809 г. в Арзамасе, росла в доме сурового отчима. По рассказам матери, она с детства отличалась странностями, и мать поскорее постаралась выдать замуж «дурочку»." },
  { key: "02-12", name: "Прп. Зинона, постника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Зинон Печерский, постник, подвизался в Дальних пещерах Киево-Печерского монастыря в XIV веке. Постом, молитвой и послушанием благоугодил Богу." },
  { key: "02-12", name: "прп. Зинона Каппадокийского, ученика свт. Василия Великого", kind: "saint", desc: "Преподобный Зинон, ученик святителя Василия Великого , родился в городе Понте в богатой семье. Служил при дворе императора Валента (364–378) в числе воинов, с которыми рассылались царские грамоты." },
  { key: "02-12", name: "мч. Феофила Нового", kind: "saint", desc: "Святой мученик Феофил Новый родился и воспитывался в Константинополе. Был военачальником греческих войск и сенатором. Во время войны с врагами Греческой империи святого Феофила взяли в плен." },
  { key: "02-12", name: "блгв. Петра, царя Болгарского", kind: "saint", desc: "Благоверный Петр, царь Болгарский, был сыном воинственного болгарского князя Симеона. Святой Петр отличался христианским благочестием, часто обращался к преподобному Иоанну Рыльскому (память 18 августа, 19 октября), испрашивая его молитв, духовных наставлений и советов." },
  { key: "02-12", name: "Сщмч. Владимира Хрищеновича, пресвитера", kind: "saint", desc: "Священномученик Владимир родился в 1876 году в деревне Гезгалы Лидского уезда Виленской губернии в семье крестьянина Ивана Хрищеновича. В 1911 году Владимир окончил Слуцкое духовное училище и поступил служить псаломщиком в церковь святителя Николая чудотворца в селе Горки Бобруйского уезда Минской губернии." },
  { key: "02-12", name: "мч. Стефана Наливайко", kind: "saint", desc: "Степан (Стефан) Пименович Наливайко (1898 – 1945), мученик. Родился в 1898 году в селе Константиновке Бердянского уезда Таврической губернии в благочестивой крестьянской семье Пимена и Евфросинии Наливайко." },
  { key: "02-13", name: "свт. Никиты, затворника Печерского, епископа Новгородского", kind: "saint", desc: "Святитель Никита, епископ Новгородский, в молодые годы поступил в Киево-Печерский монастырь и вскоре пожелал уйти в затвор. Игумен предупреждал его о преждевременности такого подвига для молодого инока, но он, понадеявшись на свои силы, не послушался." },
  { key: "02-13", name: "мц. Трифены Кизической", kind: "saint", desc: "Святая мученица Трифена происходила из города Кизика. Она добровольно предала себя на страдания за Христа. Ее бросали в раскаленную печь, вешали на высоком дереве, бросали с высоты на острые камни, отдавали на съедение зверям, но Господь хранил ее невредимой." },
  { key: "02-14", name: "Предпразднство Сретения Господня", kind: "feast", desc: "По прошествии сорока дней после рождества Господа нашего Иисуса Христа, и по исполнении дней законного очищения, Пречистая и Преблагословенная Дева Матерь, вместе со святым Иосифом обрученником, пришла из Вифлеема в Иерусалим ко храму Божию, принеся сорокадневного младенца Христа для исполнения закона Моисеева." },
  { key: "02-14", name: "Мч. Трифона Апамейского", kind: "saint", desc: "Святой мученик Трифон родился в одной из областей Малой Азии – Фригии, неподалеку от города Апамеи в селении Кампсада. С юных лет Господь даровал ему силу изгнания бесов и исцеления различных болезней." },
  { key: "02-14", name: "прп. Петра Галатийского, Молчальника", kind: "saint", desc: "Современник и друг преподобного Петра блаженный Феодорит , епископ Кирский, сообщает об этом великом подвижнике следующие высоко назидательные сведения." },
  { key: "02-14", name: "прп. Вендимиана, пустынника Вифинийского", kind: "saint", desc: "Преподобный Вендимиан родился в Мизии. В молодости был учеником святого Авксентия, одного из отцов IV Вселенского Собора (451). Поселившись в обители, основанной преподобным Авксентием (память 14 февраля) на горе Оксии, недалеко от Халкидон" },
  { key: "02-14", name: "Сщмч. Михаила Белороссова, пресвитера", kind: "saint", desc: "Священномученик Михаил родился 11 мая 1869 года в городе Романове-Борисоглебске Ярославской губернии [1] в семье диакона Павла Белороссова. В 1890 году Михаил окончил Ярославскую Духовную семинарию и служил псаломщиком в церкви Николы на Меленках в Ярославле." },
  { key: "02-14", name: "сщмч. Николая Мезенцева, пресвитера", kind: "saint", desc: "Священномученик Николай родился 8 сентября 1863 года в селе Красная Слободка Трубчевского уезда Орловской губернии в семье псаломщика Дмитрия Мезенцева." },
  { key: "02-15", name: "Сретение Господа Бога и Спаса нашего Иисуса Христа", kind: "feast", desc: "По прошествии сорока дней после рождества Господа нашего Иисуса Христа, и по исполнении дней законного очищения, Пречистая и Преблагословенная Дева Матерь, вместе со святым Иосифом обрученником, пришла из Вифлеема в Иерусалим ко храму Божию, принеся сорокадневного младенца Христа для исполнения закона Моисеева." },
  { key: "02-15", name: "Собор святых Пермской митрополии", kind: "feast", desc: "Дата празднования Собора святых Пермской митрополии – первое воскресенье после 11 февраля (29 января). Собор утвержден благословением Святейшего Патриарха Кирилла от 4 января 2015 года." },
  { key: "02-16", name: "Попразднство Сретения Господня", kind: "feast", desc: "По прошествии сорока дней после рождества Господа нашего Иисуса Христа, и по исполнении дней законного очищения, Пречистая и Преблагословенная Дева Матерь, вместе со святым Иосифом обрученником, пришла из Вифлеема в Иерусалим ко храму Божию, принеся сорокадневного младенца Христа для исполнения закона Моисеева." },
  { key: "02-16", name: "Симеона Богоприимца", kind: "saint", desc: "Праведный Симеон Богоприимец был, по свидетельству святого евангелиста Луки, одним из избранников Божиих, ожидавших утешения Израилева, и Дух Святой пребывал на нем ( Лк.2:25 )." },
  { key: "02-16", name: "Анны Пророчицы", kind: "saint", desc: "Св. Анна Пророчица, 84-летняя вдова из колена Асирова, удостоилась встретить Младенца Иисуса в храме при Сретении. За свою благочестивую жизнь она получила от Бога дар пророчества." },
  { key: "02-16", name: "равноап. Николая (Касаткина), архиепископа Японского", kind: "saint", desc: "Святой равноапостольный Николай, архиепископ Японский, в миру Иван Димитриевич Касаткин, родился 1 августа 1836 года в Березовском погосте, Вольского уезда, Смоленской губернии, где его отец служил диаконом." },
  { key: "02-16", name: "Блгв. кн. Романа Угличского", kind: "saint", desc: "Благоверный князь Роман Угличский, сын Угличского князя Владимира и княгини Фотинии, племянник святого Василька Ростовского (&dagger; 1238; память 4 марта), родился 1 октября 1235 года." },
  { key: "02-16", name: "свт. Симеона, епископа Полоцкого и Тверского", kind: "saint", desc: "Св. Симеон был первым епископом Тверским. Происходил он, как полагают, из князей Полоцких. Смуты и скорби того времени заставили его, тогда уже епископа, переселиться в Тверь, где он был с радостью принят князем Ярославом Ярославичем." },
  { key: "02-16", name: "свт. Игнатия Мариупольского, митрополита", kind: "saint", desc: "Родиной будущего святого был остров Фермия в Греции, где он родился в начале XVIII века в знатном роде Гозадини. С юных лет он воспитывался на святой горе Афон, своеобразном &quot;монашеском государстве&quot;, где подвизался его близкий родственник." },
  { key: "02-16", name: "прор. Азарии", kind: "saint", desc: "Сын Одеда, пророчествовал во дни Асы, царя иудейского, в Х веке до Р. Х. Он убеждал царя и народ оставить идолослужение и верно служить истинному Богу." },
  { key: "02-16", name: "мч. Власия (Вукола) Кесарийского (Каппадокийского)", kind: "saint", desc: "Святой Власий Кесарийский – Вукол – жил в III веке, происходил из Кесарии Каппадокийской (Малая Азия) и был пастухом (по-гречески вукол ). Когда настало гонение на христиан, святой Власий добровольно предал себя в руки мучителей, его подвергли истязаниям, били воловьими жилами, но Господь исцелил его раны." },
  { key: "02-16", name: "Иоанна Томилова", kind: "saint", desc: "Священномученик Иоанн родился 18 февраля 1878 года в селе Еськи Бежецкого уезда Тверской губернии в семье священника Иоанна Томилова. Окончив Тверскую Духовную семинарию, он в 1904 году был рукоположен во священника ко храму в родном селе Еськи на место отца." },
  { key: "02-16", name: "Тимофея Изотова", kind: "saint", desc: "Священномученик Тимофей родился в 1875 году в городе Симферополе Таврической губернии в семье садовника Спиридона Изотова. Образование он получил в церковно-приходской школе." },
  { key: "02-16", name: "Адриана Троицкого", kind: "saint", desc: "Священномученик Адриан родился 12 июня 1872 года в селе Билярском Чистопольского уезда Казанской губернии в семье диакона Александра Троицкого. После окончания Чебоксарского духовного училища он поступил в Чебоксарское городское училище, но последнее не окончил." },
  { key: "02-16", name: "Василия Залесского", kind: "saint", desc: "Священномученик Василий родился 4 февраля 1887 года в селе Федоровка Астраханского уезда Астраханской губернии в семье псаломщика Даниила Залесского. В 1908 году Василий окончил Астраханскую Духовную семинарию и 29 августа того же года был " },
  { key: "02-16", name: "прмч. Владимира (Загребы), иеромонаха", kind: "saint", desc: "Преподобномученик Владимир родился в 1870 году в слободе Кутейниково Амвросиевского уезда Донской губернии в благочестивой семье крестьянина Филиппа Загребы и в крещении наречен был Василием." },
  { key: "02-17", name: "Попразднство Сретения Господня", kind: "feast", desc: "По прошествии сорока дней после рождества Господа нашего Иисуса Христа, и по исполнении дней законного очищения, Пречистая и Преблагословенная Дева Матерь, вместе со святым Иосифом обрученником, пришла из Вифлеема в Иерусалим ко храму Божию, принеся сорокадневного младенца Христа для исполнения закона Моисеева." },
  { key: "02-17", name: "Прп. Исидора Пелусиотского", kind: "saint", desc: "Преподобный Исидор Пелусиот жил в IV–V веках. Родом из Александрии. Вырос в среде благочестивых христиан. Он состоял в родстве с Феофилом, архиепископом Александрийским, и его преемником святым Кириллом ." },
  { key: "02-17", name: "блгв. вел. кн. Георгия (Юрия) Всеволодовича Владимирского", kind: "saint", desc: "Святой благоверный князь Георгий (1189–1238) был вторым сыном великого князя Всеволода Большое Гнездо . В 1212 году после смерти отца и старшего брата Константина он унаследовал Владимирский великокняжеский престол.", lifeId: "georgiy" },
  { key: "02-17", name: "прп. Кирилла Новоезерского (Новгородского)", kind: "saint", desc: "Прп. Кирилл Белый, Новоезерский (Новгородский), уроженец Галича, с юности стремился к монашеству. Тайно уйдя из дома, он принял постриг в обители прп. Корнилия Комельского, где его нашли родители, также принявшие иночество." },
  { key: "02-17", name: "мч. Иадора", kind: "saint", desc: "Мученик Иадор (&dagger; 249–251) пострадал в правление императора Декия. Этот святой не упоминается в греческих календарях. По всей видимости, его имя появилось в Киевском месяцеслове 1672 г." },
  { key: "02-17", name: "сщмч. Авраамия, епископа Арвильского", kind: "saint", desc: "Священномученик Аврамий (Авраамий), епископ Арвильский, пострадал во время гонения на христиан в Персии при царе Сапоре II. Когда святого принуждали отречься от Христа и поклониться солнцу, он ответил: &quot;Какое безумие оставить Творца и " },
  { key: "02-17", name: "прп. Николая исп., игумена Студийского", kind: "saint", desc: "Преподобный Николай исповедник, игумен Студийский, жил в IX веке. Он родился на острове Крите в селении Кедонии в христианской семье. В возрасте 10 лет родители отправили его в Константинополь к дяде, блаженному Феофану, который был иноком Студийского монастыря." },
  { key: "02-17", name: "Сщмч. Мефодия (Красноперова), епископа Петропавловского", kind: "saint", desc: "Священномученик Мефодий родился 30 июля 1868 года в селе Вятском Сарапульского уезда Вятской губернии в семье псаломщика Платона Красноперова и в крещении был наречен Михаилом." },
  { key: "02-17", name: "Евстафия Сокольского", kind: "saint", desc: "Священномученик Евстафий родился 20 февраля 1874 года в селе Рождество Медынского уезда Калужской губернии в семье диакона Петра Сокольского. В 1895 году Евстафий Петрович окончил Духовную семинарию и в течение года служил сельским учителем." },
  { key: "02-17", name: "Иоанна Артоболевского", kind: "saint", desc: "Священномученик Иоанн родился 9 января 1872 года в селе Проказна Лунинской волости Мокшанского уезда Пензенской губернии в семье священника Алексея Артоболевского." },
  { key: "02-17", name: "Александра Минервина", kind: "saint", desc: "Священномученик Александр родился 22 мая 1888 года в селе Петровском Бронницкого уезда Московской губернии в семье священника Петра Павловича Минервина." },
  { key: "02-17", name: "Сергия Соловьева", kind: "saint", desc: "Священномученик Сергий родился 26 сентября 1883 года в селе Шубино Бронницкого уезда Московской губернии в семье священника Михаила Константиновича и его супруги Екатерины Дмитриевны Соловьевых; у них было десять человек детей, и все сыновья в разные годы окончили Московскую Духовную семинарию." },
  { key: "02-17", name: "Иоанна Алешковского", kind: "saint", desc: "Священномученик Иоанн родился 13 февраля 1888 года в селе Новое Ракитино Лебедянского уезда Воронежской губернии в семье священника Григория Алешковского." },
  { key: "02-17", name: "Александра Соколова", kind: "saint", desc: "Священномученик Александр родился 8 августа 1881 года в селе Раменье Волоколамского уезда Московской губернии в семье священника Павла Соколова. В 1892 году Александр окончил сельскую школу, в 1898 году — Волоколамское духовное училище, в 1904 году — Вифанскую Духовную семинарию и год работал учителем [1] ." },
  { key: "02-18", name: "Попразднство Сретения Господня", kind: "feast", desc: "По прошествии сорока дней после рождества Господа нашего Иисуса Христа, и по исполнении дней законного очищения, Пречистая и Преблагословенная Дева Матерь, вместе со святым Иосифом обрученником, пришла из Вифлеема в Иерусалим ко храму Божию, принеся сорокадневного младенца Христа для исполнения закона Моисеева." },
  { key: "02-18", name: "Мц. Агафии Панормской (Палермской)", kind: "saint", desc: "Сия мученица почитается в нашем простом народе заступницею от вреда огненного. Она жила в Сицилии при безбожном гонителе христиан Декии и происходила от знатных родителей, воспитавших ее в истинном благочестии." },
  { key: "02-18", name: "свт. Феодосия, архиепископа Черниговского", kind: "saint", desc: "Свт. Феодосий, архиепископ Черниговский (1630-е – 1696), происходил из дворянского рода. Образование получил в Киево-Братской коллегии. Принял монашество в Киево-Печерской лавре." },
  { key: "02-18", name: "Прмч. Николая (Цикуры), послушника", kind: "saint", desc: "Преподобномученик [1] Николай (Цикура) был экономом архиерейского дома при архиепископе Омском и Павлодарском Сильвестре (Ольшевском) и сопровождал его во время поездок по России, терпя вместе с архиереем все тяготы послереволюционной разрухи." },
  { key: "02-18", name: "прмц. Александры Каспаровой, послушницы", kind: "saint", desc: "Преподобномученица Александра (Каспарова) родилась в 1882 году. 18 февраля 1942 года 60-летняя послушница пострадала от рук богопротивной власти, тем самым сподобившись принять мученический венец." },
  { key: "02-18", name: "мч. Михаила Амелюшкина", kind: "saint", desc: "Мученик Михаил родился 24 сентября 1893 года в деревне Починки Богородского уезда [1] Московской губернии в семье крестьянина Спиридона Амелюшкина. Окончив сельскую школу, он занимался крестьянским хозяйством." },
  { key: "02-18", name: "Елецкая-Черниговская", year: "1060", kind: "saint", desc: "Когда прп. Антоний Печерский (скон. 1072 г.) в 1060 году был изгнан из Киева великим князем Изяславом (1054–1073), он тайно удалился в пределы Чернигова." },
  { key: "02-18", name: "Дивногорская-Сицилийская", year: "1092", kind: "saint", desc: "Дивногорская-Сицилийская икона Божией Матери получила свое наименование по месту своего первоначального пребывания и прославления в Успенском Дивногорском монастыре, в бывшем Острогожском уезде, Воронежской губернии, а Сицилийской названа п" },
  { key: "02-18", name: "Взыскание погибших", kind: "saint", desc: "С незапамятных времен русский народ, свято веря во всесильную помощь Пресвятой Богородицы, усвоил Ей именование &quot;Взыскание погибших&quot;, как последнему прибежищу, последней надежде погибающих людей." },
  { key: "02-19", name: "Отдание праздника Сретения Господня", kind: "feast", desc: "По прошествии сорока дней после рождества Господа нашего Иисуса Христа, и по исполнении дней законного очищения, Пречистая и Преблагословенная Дева Матерь, вместе со святым Иосифом обрученником, пришла из Вифлеема в Иерусалим ко храму Божию, принеся сорокадневного младенца Христа для исполнения закона Моисеева." },
  { key: "02-19", name: "Прп. Вукола, епископа Смирнского", kind: "saint", desc: "Преподобный Вукол, епископ Смирнский, ученик святого апостола и евангелиста Иоанна Богослова, был им поставлен первым епископом Смирнской Церкви (Малая Азия)." },
  { key: "02-19", name: "свт. Фотия, патриарха Константинопольского", kind: "saint", desc: "Святитель Фотий, патриарх Константинопольский, жил в IX веке, происходил из семьи ревностных христиан. Отец его скончался мученической смертью за защиту икон." },
  { key: "02-19", name: "мч. Иулиана Эмесского (Емисского)", kind: "saint", desc: "Святой мученик Иулиан был родом из финикийского города Эмесы, пострадал в 312 году при императоре Максимиане. Он был искусным врачом, исцелял болезни не только телесные, но и душевные и многих людей обратил к вере во Христа Спасителя." },
  { key: "02-19", name: "прп. Шио Мгвимского (VI)", kind: "saint", desc: "Преподобный Шио (Симеон) Мгвимский (от груз. мгвиме – пещера – Печерский) родился в Антиохии Сирской. Родители его были христианами и воспитывали своего сына как единственного наследника." },
  { key: "02-19", name: "сщмч. Василия Надеждина, пресвитера", kind: "saint", desc: "Священномученик Василий родился 12 января 1895 года в Москве в семье Федора Алексеевича и Софьи Павловны Надеждиных. Федор Алексеевич служил чиновником Дворцового управления в звании коллежского асессора и доводился родственником архиепископу Анастасию (Грибановскому)." },
  { key: "02-19", name: "сщмч. Александра Телемакова, пресвитера", kind: "saint", desc: "Священномученик Александр родился 6 декабря 1870 года в городе Сызрани Симбирской губернии в семье чиновника Николая Телемакова, служившего в государственном казначействе." },
  { key: "02-20", name: "Прп. Парфения, епископа Лампсакийского", kind: "saint", desc: "Святитель Парфений, епископ Лампсакийский, был родом из города Мелитополя (Малая Азия), где его отец Христофор служил диаконом. Юноша не был научен грамоте, но хорошо усвоил Божественное Писание, присутствуя в храме при богослужениях." },
  { key: "02-20", name: "прп. Луки Елладского", kind: "saint", desc: "Преподобный Лука Елладский был родом из греческого селения Кастории. Сын бедных земледельцев, преподобный с детства много трудился, работал в поле, пас овец." },
  { key: "02-20", name: "Мучеников 1003 Никомидийских", year: "303", kind: "saint", desc: "Святые мученики, в Никомидии пострадавшие, были слугами четырех сановников: Васса, Евсевия, Евтихия и Василида, которые вместе со своими женами пострадали за Христа (память 20 января) в 303 году при императоре Диоклитиане (284–305)." },
  { key: "02-20", name: "Сщмч. Александра Талызина, пресвитера", kind: "saint", desc: "Священномученик Александр родился 15 августа 1870 года в селе Типня Весьегонского уезда Тверской губернии в семье священника Иоанна Талызина. После окончания Духовной семинарии Александр Иванович был рукоположен во священника и служил в храмах Тверской епархии." },
  { key: "02-20", name: "сщмч. Алексия Троицкого, пресвитера", kind: "saint", desc: "Священномученик Алексий родился 1 февраля 1875 года в городе Коломне Московской губернии в семье псаломщика Богословской церкви Николая Троицкого, он умер в 1893 году, и его супруга после этого стала работать просфорницей при одной из городских церквей; она скончалась в 1903 году." },
  { key: "02-21", name: "Собор всех преподобных отцов, в подвиге просиявших", kind: "feast", desc: "Приготовление к Святой Четыредесятнице начинается вскоре после праздника Богоявления. Собственно Четыредесятницу предваряют четыре подготовительные Недели (воскресенья): о мытаре и фарисее (без седмицы), о блудном сыне, мясопустная (мясо-отпустная) и сыропустная (сыро-отпустная, сырная) (с седмицами)." },
  { key: "02-21", name: "Вмч. Феодора Стратилата", kind: "saint", desc: "Вмч. Феодор Стратилат, военачальник из Евхаит, прославился доблестью и верой. Убил чудовищного змея с Божией помощью, обратил в христианство жителей Гераклеи." },
  { key: "02-21", name: "прор. Захарии Серповидца, из 12-ти", kind: "saint", desc: "Пророк Захария Серповидец из 12-ти малых пророков происходил из колена Левиина, в книге Неемии назван главою священнического рода. Он был с юношеского возраста призван к пророческому служению и стал, по дивному слову церковного песнопения, &quot;зрителем премирных видений&quot;." },
  { key: "02-21", name: "Свт. Саввы II, архиепископа Сербского", kind: "saint", desc: "Свт. Савва II (ок. 1200–1271) ‒ третий архиепископ Сербский, племянник св. Саввы Сербского и сын св. короля Стефана Первовенчанного. Отказавшись от светской власти, принял монашество на Афоне в Хиландаре, совершил паломничество в Иерусалим." },
  { key: "02-21", name: "Симеона Кульгавца", kind: "saint", desc: "Священномученик Симеон родился 2 февраля 1882 года в посаде Ломазы Бельского уезда Седлецкой губернии в семье крестьянина Демьяна Кульгавца. Отец умер, когда Семену было три года." },
  { key: "02-21", name: "Андрея Добрынина", kind: "saint", desc: "Священномученик Андрей родился 10 августа 1874 года в селе Рождествено-Прозорово Мологского уезда Ярославской губернии в семье священнослужителя Николая Добрынина." },
  { key: "02-21", name: "Сергия Любомудрова", kind: "saint", desc: "Священномученик Сергий родился 4 июля 1878 года в селе Мышцы Касимовского уезда Рязанской губернии в семье священника Иоанна Любомудрова. В 1899 году, окончив три класса Рязанской Духовной семинарии, он стал служить псаломщиком в соборе в городе Пронске." },
  { key: "02-21", name: "Петра Маркова", kind: "saint", desc: "Петр Иванович Марков родился 15 октября (по другим данным 14 августа) 1881 года в селе Сеченки Бронницкого уезда Московской губернии в многодетной семье псаломщика." },
  { key: "02-21", name: "сщмч. Александра Абиссова, пресвитера", kind: "saint", desc: "Священномученик Александр родился 19 февраля 1873 года в селе Мормужино Пошехонского уезда Ярославской губернии в семье священника Афанасия Евграфовича Абиссова и его супруги Клавдии Николаевны." },
  { key: "02-22", name: "Мч. Никифора, из Антиохии Сирской", kind: "saint", desc: "Святой мученик Никифор жил в городе Антиохии Сирийской. В этом же городе жил также пресвитер Саприкий, с которым Никифор был очень дружен, так что их считали за родных братьев." },
  { key: "02-22", name: "Обретение мощей свт. Иннокентия (Кульчицкого), епископа Иркутского", kind: "saint", desc: "Прославленный во святых, дивный в чудесах, чтимый ближними и дальними, чудотворец Иннокентий, первый епископ Иркутский, родился в конце XVII века в Малороссии, в Черниговской губернии." },
  { key: "02-22", name: "Обретение мощей свт. Тихона (Беллавина), патриарха Московского и всея Руси", kind: "saint", desc: "Свт. Тихон (Беллавин, 1865–1925) – одиннадцатый Патриарх Московский и всея Руси. Принял монашество в 1891 году. Управлял епархиями в Северной Америке, Ярославле, Вильно, проявляя особую заботу о пастве." },
  { key: "02-22", name: "Прп. Панкратия Печерского, в Дальних пещерах", kind: "saint", desc: "Жил в XIII веке, подвизался в Киево-Печерском монастыре в сане иеромонаха. Прославился в подвигах поста, а также чудотворениями, исцелениями болящих. Был погребен в Дальних (Феодосиевых) пещерах." },
  { key: "02-22", name: "Маркиана (Маркелла), епископа Сикелийского", kind: "saint", desc: "Сщмч. Маркиан, бывший последователь Симона Волхва, почитается как первый епископ Сиракузский, обращенный в христианство через апостола Петра. Около 39 года он был направлен на проповедь в Сицилию, где основал христианскую общину в пещере близ Сиракуз." },
  { key: "02-22", name: "Филагрия, епископа Кипрского", kind: "saint", desc: "Священномученики Маркелл, Филагрий и Панкратий были учениками святого апостола Петра и поставлены им епископами: святой Маркелл – Сицилийским, Филагрий – Кипрским и Панкратий – Тавроменийским." },
  { key: "02-22", name: "Панкратия, епископа Тавроменийского", kind: "saint", desc: "Сщмч. Панкратий Тавроменийский родился в Антиохии и жил во времена земной жизни Христа. Услышав о благовестии, он уверовал во Христа, познакомился с апостолом Петром и после смерти родителей удалился в горы для молитвы." },
  { key: "02-22", name: "Сщмч. Василия Измайлова, пресвитера", kind: "saint", desc: "Священномученик Василий (Василий Васильевич Измайлов) родился 4 июня 1885 года в городе Вышнем Волочке Тверской губернии. В 1905 году Василий окончил Минскую Духовную семинарию, в 1910-м — Санкт-Петербургскую Духовную академию и был направл" },
  { key: "02-22", name: "сщмч. Иоанна Фрязинова, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 23 апреля 1882 года в селе Сильвачево Бронницкого уезда Московской губернии в семье священника Василия Фрязинова. Окончив первый курс Вифанской Духовной семинарии, он поступил учителем в школу." },
  { key: "02-23", name: "Блгв. кн. Анны Новгородской", kind: "saint", desc: "Святая Анна Новгородская (до Крещения Ингигерда) была старшей дочерью шведского короля святого Олофа Шетконунга (994–1022 г.), прозванного «всехристианнейшим королем»." },
  { key: "02-23", name: "прп. Прохора Печерского, в Ближних пещерах", kind: "saint", desc: "Жил этот Божий угодник в княжение Святополка, который весьма притеснял киевлян. Господь попустил тогда половцам напасть на русскую землю. На Руси настал голод и оскудение." },
  { key: "02-23", name: "прп. Лонгина Коряжемского, иеромонаха", kind: "saint", desc: "Преподобный Лонгин Коряжемский первоначально подвизался в обители преподобного Павла Обнорского, затем жил в Борисоглебском Сольвычегодском монастыре. Оттуда он со своим другом Симоном удалился вверх по Вычегде к устью реки Коряжемки." },
  { key: "02-23", name: "прав. Галины", kind: "saint", desc: "В царствование нечестивого царя Римского Севера [1] при распространении Церкви Господа нашего Иисуса Христа служение бесам стало упадать и самое идолопоклонство прекращаться." },
  { key: "02-23", name: "Сщмч. Константина Верецкого, пресвитера", kind: "saint", desc: "Константин Александрович Верецкий родился 3 июня (21 мая по старому стилю) 1874 года в селе Петровском Бахмутского уезда Екатеринославской губернии в семье священника." },
  { key: "02-23", name: "Петра Грудинского", kind: "saint", desc: "Священномученик Петр родился в 1877 году в городе Глуске Минской губернии в семье крестьянина Феофила Грудинского. Петр Феофилович получил образование в городском училище и затем работал в волостном правлении и в страховом ведомстве." },
  { key: "02-23", name: "Валериана Новицкого", kind: "saint", desc: "Новицкий Валериан Васильевич (1897 – 1930), священник, священномученик. Жена — Доминикия Игнатьевна. Дочери — Нина и Ирина, сын — Евгений. Родился в 1897 году в деревне Грабово Минской губернии, старший сын протоиерея Василия Дионисиевича Новицкого (+ 1921), который служил в деревне Телядовичи Копыльского района Минской области, и матушки Людмилы Николаевны." },
  { key: "02-23", name: "Огневидная", kind: "saint", desc: "Древний византийский образ, упоминаемый с 598 года [1] и именуемый «Кафрептис» — «Зерцало», в русском изводе известный как «Огневидная» икона Пресвятой Богородицы, получил распространение в Русской Церкви только в XVIII веке." },
  { key: "02-24", name: "Сщмч. Власия, епископа Севастийского", kind: "saint", desc: "С юных лет св. Власий был кроток и благочестив. Граждане севастийские, ценя такие его качества, выбрали его в епископы, каковое звание он носил с великой честью." },
  { key: "02-24", name: "блгв. кн. Всеволода, во Святом Крещении Гавриила, Новгородского, Псковского", kind: "saint", desc: "Святой благоверный князь Всеволод, в Крещении Гавриил, Псковский, внук Владимира Мономаха, родился и почти всю жизнь прожил в Новгороде, где в 1088–1093 и 1095–1117 годах княжил его отец, святой благоверный князь Мстислав-Феодор Великий (&dagger; 15 апреля 1132)." },
  { key: "02-24", name: "прп. Димитрия Прилуцкого, игумена Вологодского", kind: "saint", desc: "Сей преподобный и богоносный отец наш Димитрий родился в нашей стране в городе Переяславле у благочестивых родителей. Был крещен во имя Отца и Сына и Святаго Духа и с детства приучен к божественным книгам." },
  { key: "02-24", name: "прп. Кассиана Босого, Волоколамского", kind: "saint", desc: "Сей честной старец родился в городе Переяславле у православных родителей, Козьма было его имя. И когда достиг он совершеннолетия, то сделался физически крепок и мужественен и стал бывать у тех, кто жил в царских палатах." },
  { key: "02-24", name: "Прав. Феодоры, царицы Греческой, восстановившей почитание святых икон", kind: "icon", desc: "Праведная царица Феодора была супругой греческого царя Феофила-иконоборца (829–842), но не разделяла ереси мужа и тайно почитала святые иконы. После его смерти, когда святая Феодора управляла государством вместо малолетнего сына Михаила, он" },
  { key: "02-25", name: "Иверской иконы Божией Матери", kind: "icon", desc: "Иверская икона Божией Матери, находящаяся на Афоне , прославилась многими чудесами. Слух о чудотворном образе через паломников распространился по России." },
  { key: "02-25", name: "Свт. Мелетия, архиепископа Антиохийского", kind: "saint", desc: "Святой Мелетий, архиепископ Антиохийский, был сначала епископом Севастийским в Армении (ок. 357), а впоследствии был вызван императором Констанцием в Антиохию для защиты от арианской ереси и получил Антиохийскую кафедру." },
  { key: "02-25", name: "свт. Алексия Московского, митрополита Киевского и всея Руси, чудотворца", kind: "saint", desc: "Родился в Москве в семье боярина. В 12 лет услышал голос Божий: «Алексий! Ты будешь ловить людей». Принял постриг в Богоявленском монастыре, где провёл 20 лет в подвижничестве." },
  { key: "02-25", name: "свт. Мелетия (Леонтовича), архиепископа Харьковского", kind: "saint", desc: "Святитель Мелетий, архиепископ Харьковский и Ахтырский (в миру Михаил Иванович Леонтович), родился 17 ноября (по новому стилю) 1784 года в селе Старые Санжары Полтавской области, в семье купца Иоанна Леонтовича." },
  { key: "02-25", name: "свт. Антония, патриарха Константинопольского", kind: "saint", desc: "Родиной святого была Азия, но вся жизнь его от юных лет и до кончины протекла в Константинополе. Родился он около 829 года от богатых и благочестивых родителей." },
  { key: "02-25", name: "прп. Мелетия Ипсенийского", kind: "saint", desc: "Преподобный Мелетий Ипсенийский родился в конце XVIII века в селении Лардос на острове Родос в Османской империи (ныне – Греция), в семье благочестивых родителей Николая и Стаматии." },
  { key: "02-26", name: "Прп. Мартиниана Кесарийского (Палестинского)", kind: "saint", desc: "Преподобный Мартиниан с 18 лет поселился в пустыне, близ города Кесарии Палестинской, где пробыл в подвигах и безмолвии 25 лет, удостоившись благодатного дара исцеления болезней." },
  { key: "02-26", name: "свт. Серафима (Соболева), архиепископа Богучарского", kind: "saint", desc: "Николай Борисович Соболев — будущий архиепископ Серафим — родился в городе Рязани 1 декабря (по старому стилю) 1881 года в семье мещанина Бориса Матвеевича Соболева и его жены Марии Николаевны." },
  { key: "02-26", name: "прп. Евлогия, архиепископа Александрийского", kind: "saint", desc: "Преподобный Евлогий, архиепископ Александрийский, был одним из просвещенных и деятельных иерархов VI века. В начале он был игуменом Богородичной Юстиниановой обители в Антиохии, а затем избран на кафедру города Александрии, где и прослужил 27 лет." },
  { key: "02-26", name: "прп. Симеона Мироточивого, в миру Стефана Неманя, царя Сербского", kind: "saint", desc: "Родившись в 1114 году от жупана Давида, Стефан (Симеон в монашестве) был младшим из четырех сыновей. Даже в раннем возрасте он правил столь мудро и благочестиво, что после смерти отца ему была отдана в управление большая часть страны; и потом он всю жизнь страдал от гнева своих братьев." },
  { key: "02-26", name: "Собор святых Омской митрополии", kind: "feast", desc: "Собор святых Омской митрополии был внесен в месяцеслов Русской Православной Церкви в 2015 году по благословению Патриарха Московского и всея Руси Кирилла." },
  { key: "02-26", name: "Василия Триумфова", kind: "saint", desc: "Священномученик Василий (Василий Александрович Триумфов) родился в 1848 году. В 1870 году он окончил Псковскую Духовную семинарию и был рукоположен во священника ко храму Покрова Пресвятой Богородицы в селе Бежаницы Новоржевского уезда Псковской губернии [1] ." },
  { key: "02-26", name: "Гавриила Преображенского", kind: "saint", desc: "Священномученик Гавриил родился 21 марта 1878 года в погосте Котельня Островского уезда Псковской губернии в семье священника Стефана Васильевича Преображенского." },
  { key: "02-26", name: "Зосимы Трубачева", kind: "saint", desc: "Священномученик Зосима родился 24 декабря 1893 года в селе Пучуга Сольвычегодского уезда Вологодской губернии в семье диакона Василия Трубачева и его жены Веры Петровны." },
  { key: "02-26", name: "Николая Добролюбова", kind: "saint", desc: "Священномученик Николай родился 20 апреля 1875 года в селе Маврино Богородского уезда Московской губернии в семье церковнослужителя Алексея Добролюбова." },
  { key: "02-26", name: "Василия Горбачева", kind: "saint", desc: "Священномученик Василий родился 4 апреля 1885 года в селе Нарышкино Сердобского уезда Саратовской губернии в семье крестьянина Григория Горбачева. Василий окончил церковноприходскую школу и до двадцати лет жил с родителями." },
  { key: "02-26", name: "Иоанна Покровского", kind: "saint", desc: "Священномученик Иоанн родился в 1874 году в селе Аксиньино Коломенского уезда Московской губернии в семье священника Семена Покровского. Окончил Московскую Духовную семинарию и в 1897 году был рукоположен во священника." },
  { key: "02-26", name: "Леонтия Гримальского", kind: "saint", desc: "Священномученик Леонтий родился 10 июля 1869 года в селе Лодыженка Уманского уезда Киевской губернии в семье псаломщика Степана Гримальского. В 1892 году Леонтий Степанович окончил Киевскую Духовную академию и поступил учителем в церковноприходскую школу в селе Русаловка Уманского уезда." },
  { key: "02-26", name: "Владимира Покровского", kind: "saint", desc: "Священномученик Владимир родился 6 июня 1871 года в семье священника Алексея Покровского в городе Москве. Окончив Духовную семинарию, Владимир Алексеевич в 1894 году был рукоположен во священника к Вознесенскому храму в селе Бурцево Верейского уезда Московской губернии, здесь он прослужил более сорока лет." },
  { key: "02-26", name: "Парфения Грузинова", kind: "saint", desc: "Священномученик Парфений родился 30 января 1874 года в селе Рязанцы Богородского уезда Московской губернии в семье псаломщика Василия Грузинова, прослужившего тридцать лет в Троицкой церкви в Рязанцах [1] ." },
  { key: "02-27", name: "Прп. Авксентия Вифинского", kind: "saint", desc: "Преподобный Авксентий, по происхождению сириец, служил при дворе императора Феодосия Младшего (418–450). Он был известен как добродетельный, ученый и мудрый человек и имел дружбу со многими благочестивыми мужами своего времени." },
  { key: "02-27", name: "равноап. Кирилла, учителя Словенского", kind: "saint", desc: "Святые равноапостольные первоучители и просветители славянские, братья Кирилл и Мефодий происходили из знатной и благочестивой семьи, жившей в греческом городе Солуни.", lifeId: "kirill-mefodiy" },
  { key: "02-27", name: "Прп. Исаакия, затворника Печерского, в Ближних пещерах", kind: "saint", desc: "Невозможно избегнуть человеку искушений. Если искуситель к Самому Господу в пустыне дерзнул приступить ( Мф.4:1-11 ), то тем более пытается он искушать рабов Господних." },
  { key: "02-27", name: "12-ти греков, строителей соборной Успенской церкви Киево-Печерской Лавры", year: "XI", kind: "feast", desc: "Соборная Успенская церковь Киево-Печерской лавры , заложенная прпп. Антонием и Феодосием в 1073 году, 15 лет возводилась греческими зодчими и иконописцами." },
  { key: "02-27", name: "прп. Марона, пустынника Сирийского", kind: "saint", desc: "Преподобный Марон избрал для себя подвиг беспокровного жития. Поставив себе эту цель, он взошел на одну гору, которая чтилась язычниками (она находилась в Сирии, недалеко от Антиохии), нашел там оставленный язычниками храм и поселился в нем." },
  { key: "02-27", name: "свт. Авраамия, епископа Каррийского", kind: "saint", desc: "Святой Авраамий, епископ Каррийский, жил в середине IV и начале V веков, был родом из города Кира. В молодые годы поступил в монастырь. Затем он избрал для своих подвигов Ливанские горы, где и жил отшельником." },
  { key: "02-27", name: "прп. Илариона Грузина, Святогорца, иеросхимонаха (1864)", kind: "saint", desc: "Преподобный Иларион Грузин, Святогорец (Картвели; Новый; Афонский; Имеретинский) (&dagger;1776–1864), в миру Иессей Канчавели (Канчишвили), родился в селении Лосиат-Хеви, близ Шорапани, Имерети, в семье Хахулии и Марии Канчавели, принадлежавших к дворянскому роду." },
  { key: "02-27", name: "сщмч. Онисима (Пылаева), епископа Тульского", kind: "saint", desc: "Священномученик Онисим родился 5 сентября 1872 года в деревне Марково Белозерского уезда Новгородской губернии в семье псаломщика Владимира Пылаева и в крещении был наречен Михаилом." },
  { key: "02-27", name: "сщмч. Трифона Радонежского, диакона", kind: "saint", desc: "Священномученик Трифон Радонежский [1] родился в 1873 году. Мученическую кончину от рук богопротивных властей 65-летнему диакону пришлось принять 27 февраля 1938 года." },
  { key: "02-28", name: "Вмч. Феодора Тирона", kind: "saint", desc: "Святой мученик Феодор Тирон родился в Евхаитах (ныне деревня Бейузю, Турция), был воином мармаритского полка в городе Амасии Понтийской области (северо-восточная область Малой Азии, тянувшаяся вдоль берега Понта Эвксинского, т." },
  { key: "02-28", name: "Ап. от 70-ти Онисима", kind: "saint", desc: "Апостол от 70-ти Онисим в молодости был рабом Филимона, христианина знатного рода, жившего в городе Колоссах Фригийской области. Провинившись в чем-то перед своим господином и боясь наказания, святой Онисим бежал в Рим, но там как беглый раб попал в тюрьму." },
  { key: "02-28", name: "Прп. Пафнутия, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Память 15 февраля, в Соборе преподобных отцев Киево-Печерских Дальних Пещер (28 августа) и в Соборе всех преподобных отцов Киево-Печерских. Непрестанно плакал и вздыхал всю свою жизнь о времени разлучения души с телом, как окружат человека " },
  { key: "02-28", name: "прп. Пафнутия и дочери его", kind: "saint", desc: "Прп. Пафнутий был глубоко верующим, благочестивым христианином. Его супруга умерла рано, и Пафнутий один воспитывал своего единственного ребенка – преп." },
  { key: "02-28", name: "Евфросинии Александрийской", kind: "saint", desc: "Прп. Евфросиния Александрийская (V век) родилась в знатной семье. После смерти матери её воспитывал благочестивый отец. Стремясь к монашеской жизни, она тайно приняла постриг и, переодевшись в мужскую одежду, под именем евнуха Измарагда поступила в тот самый мужской монастырь, который с детства посещала вместе с отцом." },
  { key: "02-28", name: "прп. Евсевия, пустынника Сирийского", kind: "saint", desc: "Преподобный Евсевий пустынник жил в IV веке и подвизался на горе близ селения Асиха в Сирии. Он проводил весьма суровую жизнь, находясь всегда под открытым небом и терпеливо перенося летний зной и зимний холод; одежду преподобный носил кожаную, питался моченым горохом и бобами." },
  { key: "02-28", name: "прп. Анфима Хиосского", kind: "saint", desc: "Святой Анфимий (Анфим) Хиосский, в миру Аргирий Ваянос, родился 1 июля 1869 года в приходе святого Луки в городе Ливадия на острове Хиос. Он был младшим из троих детей бедных, но добродетельных родителей, крестьян, Константина и Агерио." },
  { key: "02-28", name: "Николая Морковина", kind: "saint", desc: "Священномученик Николай родился 15 мая 1889 года в селе Ильгощи Кашинского уезда Тверской губернии в семье псаломщика Петра Морковина. В 1913 году он окончил Тверскую Духовную семинарию и женился на девице Марии." },
  { key: "02-28", name: "Алексия Никитского", kind: "saint", desc: "Священномученик Алексий (Алексей Михайлович Никитский) родился 6 марта 1891 года в селе Михалево Бронницкого уезда Московской губернии в семье священника, служившего в храме Рождества Христова, Михаила Павловича Никитского." },
  { key: "02-28", name: "Алексия Смирнова", kind: "saint", desc: "Священномученик Алексий родился в 1867 году в селе Гремячево Веневского уезда Тульской губернии в семье псаломщика Петра Смирнова. Когда Алексею исполнилось семь лет, умер отец и его взял на воспитание дед, служивший псаломщиком в одном из храмов Москвы." },
  { key: "02-28", name: "Симеона Кулямина, диакона", kind: "saint", desc: "Священномученик Симеон (Семен Федорович Кулямин) родился 1 сентября 1874 года в селе Ротмирово Владимирского уезда Владимирской губернии [1] в семье крестьянина Федора Кулямина; одиннадцати лет Семен поступил на текстильную фабрику учеником, а затем около двадцати восьми лет работал садовником у фабриканта Лосева." },
  { key: "02-28", name: "прмч. Павла (Козлова), иеромонаха", kind: "saint", desc: "Преподобномученик Павел родился 24 июня 1879 года в деревне Зуево Зубцовского уезда Тверской губернии в семье крестьян Федора и Марии Козловых и в крещении был наречен Петром." },
  { key: "02-28", name: "прмц. Софии Селиверстовой, послушницы", kind: "saint", desc: "Родилась 17 сентября 1871 года в селе Изнаир Сердобского уезда Саратовской губернии в семье крестьянина. Когда Софии исполнилось десять лет, умерла ее мать, и отец девочки отдал ее в приют в селе Краюшкино, который существовал в то время при женской общине, преобразованной затем в монастырь." },
  { key: "02-28", name: "Виленская", year: "1495", kind: "saint", desc: "Виленская икона Божией Матери написана святым евангелистом Лукой. Долгое время она была родовой святыней греческих императоров в Константинополе. В 1472 году икону перенесла в Москву София Палеолог, супруга великого князя Московского Иоанна III (1462–1505)." },
  { key: "02-29", name: "свт. Макария (Невского), митрополита Московского и Коломенского", kind: "saint", desc: "Свт. Макарий (Парвицкий-Невский, 1835–1926) – выдающийся миссионер, «Апостол Алтая». Окончив семинарию, он добровольно отправился в Алтайскую миссию, где принял монашество и посвятил 36 лет проповеди среди местных народов, изучив их язык и переведя богослужебные книги." },
  { key: "02-29", name: "Собор святых Новосибирской митрополии", kind: "feast", desc: "По благословению Святейшего Патриарха Московского и всея Руси Кирилла утвержден день празднования Собора святых Новосибирской митрополии – 29 февраля (в день памяти святителя Макария (Невского), митрополита Московского)." },
  { key: "02-29", name: "Мчч. Персидских в Мартирополе", year: "IV", kind: "saint", desc: "Преподобный Маруф был епископом основанного им города Тигрита (по-гречески – Мартирополь), – пограничного города Византийской империи и Персии. Он прославился своей ученостью и благочестием, писал о мучениках, пострадавших за веру Христову " },
  { key: "02-29", name: "прп. Маруфа, епископа Месопотамского", kind: "saint", desc: "Преподобный Маруф был епископом основанного им города Тигрита (по-гречески – Мартирополь), – пограничного города Византийской империи и Персии. Он прославился своей ученостью и благочестием, писал о мучениках, пострадавших за веру Христову " },
  { key: "02-29", name: "Сщмч. Петра Успенского, пресвитера", kind: "saint", desc: "Священномученик Петр родился в 1876 году в селе Алексеевском Коломенского уезда Московской губернии [1] в семье священнослужителя Василия Успенского. По окончании Духовной семинарии Петр в 1901 году был рукоположен во диакона и в 1905 году " },
];
